import React, { useState, useEffect, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { motion, AnimatePresence } from 'framer-motion';
import { FiSend, FiPaperclip, FiSmile, FiMoreVertical, FiPhone, FiVideo } from 'react-icons/fi';
import { sendMessage, addMessage, markAsRead } from '../../store/slices/chatSlice';
import { socketService } from '../../services/api';
import MessageBubble from './MessageBubble';
import TypingIndicator from './TypingIndicator';
import FileUpload from './FileUpload';

const ChatWindow = ({ chat }) => {
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.auth);
  console.log('👤 ChatWindow: Current user ID:', user?.id);
  const { messages, isSendingMessage, typingUsers } = useSelector((state) => state.chat);
  
  const [message, setMessage] = useState('');
  const [showFileUpload, setShowFileUpload] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [typingTimeout, setTypingTimeout] = useState(null);
  
  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  const otherParticipant = chat.participants?.find(p => p.id !== user?.id);

  // Scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Mark messages as read when chat is opened
  useEffect(() => {
    const chatId = chat?.id || chat?._id;
    if (chatId) {
      dispatch(markAsRead(chatId));
    }
  }, [chat?.id, chat?._id, dispatch]);

  // Set up socket listeners
  useEffect(() => {
    const chatId = chat?.id || chat?._id;
    if (chatId) {
      console.log('🚪 Joining chat room:', chatId);
      socketService.joinChat(chatId);
      
      // Listen for new messages
      socketService.onReceiveMessage((messageData) => {
        console.log('🔔 Received message via socket:', messageData);
        console.log('🔔 Current chatId:', chatId);
        console.log('🔔 Message chatId:', messageData.chatId);
        console.log('🔔 Message sender:', messageData['sender.id'] || messageData.senderId);
        console.log('🔔 Current user:', user?.id);
        
        if (messageData.chatId === chatId) {
          console.log('✅ Message is for current chat, adding to state');
          dispatch(addMessage(messageData));
        } else {
          console.log('❌ Message is for different chat:', messageData.chatId, 'current chat:', chatId);
        }
      });

      // Listen for typing indicators
      socketService.onUserTyping((data) => {
        if (data.chatId === chatId) {
          // Handle typing indicators
          console.log('User typing:', data);
        }
      });

      return () => {
        socketService.leaveChat(chatId);
      };
    }
  }, [chat?._id, chat?.id, dispatch]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    
    if (!message.trim() || isSendingMessage) return;

    // Get chatId from chat object (try both id and _id)
    const chatId = chat?.id || chat?._id;
    
    if (!chatId) {
      console.error('No chat ID available:', chat);
      return;
    }

    const messageData = {
      content: message.trim(),
      messageType: 'text'
    };

    // Send message via socket (this will handle both real-time delivery and persistence)
    console.log('📤 Sending message via socket:', { chatId, messageData, senderId: user.id });
    socketService.sendMessage(chatId, messageData, user.id);
    
    setMessage('');
    setIsTyping(false);
    
    // Clear typing timeout
    if (typingTimeout) {
      clearTimeout(typingTimeout);
    }
  };

  const handleTyping = (e) => {
    setMessage(e.target.value);
    
    const chatId = chat?.id || chat?._id;
    if (!isTyping && chatId) {
      setIsTyping(true);
      socketService.startTyping(chatId, user.id);
    }
    
    // Clear existing timeout
    if (typingTimeout) {
      clearTimeout(typingTimeout);
    }
    
    // Set new timeout
    const timeout = setTimeout(() => {
      setIsTyping(false);
      const chatId = chat?.id || chat?._id;
      if (chatId) {
        socketService.stopTyping(chatId, user.id);
      }
    }, 1000);
    
    setTypingTimeout(timeout);
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(e);
    }
  };

  const handleFileUpload = (file) => {
    // Handle file upload
    console.log('File uploaded:', file);
    setShowFileUpload(false);
  };

  return (
    <div className="h-full flex flex-col bg-white">
      {/* Chat Header */}
      <div className="flex items-center justify-between p-4 border-b border-gray-200 bg-gray-50">
        <div className="flex items-center space-x-3">
          <div className="relative">
            <div className="w-10 h-10 bg-gradient-to-r from-primary-500 to-health-500 rounded-full flex items-center justify-center">
              <span className="text-white font-medium text-sm">
                {otherParticipant?.fullName?.charAt(0)?.toUpperCase() || 'D'}
              </span>
            </div>
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-green-500 border-2 border-white rounded-full"></div>
          </div>
          
          <div>
            <h3 className="text-sm font-medium text-gray-900">
              {otherParticipant?.fullName || 'Unknown User'}
            </h3>
            <p className="text-xs text-gray-500">
              {otherParticipant?.userType === 'doctor' ? 'Doctor' : 'Patient'} • Online
            </p>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          <button className="p-2 hover:bg-gray-200 rounded-lg transition-colors">
            <FiPhone className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-2 hover:bg-gray-200 rounded-lg transition-colors">
            <FiVideo className="w-5 h-5 text-gray-600" />
          </button>
          <button className="p-2 hover:bg-gray-200 rounded-lg transition-colors">
            <FiMoreVertical className="w-5 h-5 text-gray-600" />
          </button>
        </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 chat-scrollbar">
        <AnimatePresence>
          {messages.map((msg, index) => (
            <motion.div
              key={msg.id || index}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.05 }}
            >
              <MessageBubble
                message={msg}
                isOwn={msg.sender?.id === user?.id || msg['sender.id'] === user?.id}
                showAvatar={index === 0 || (messages[index - 1]?.sender?.id !== msg.sender?.id && messages[index - 1]?.['sender.id'] !== msg['sender.id'])}
              />
            </motion.div>
          ))}
        </AnimatePresence>

        {/* Typing Indicator */}
        {typingUsers.length > 0 && (
          <TypingIndicator users={typingUsers} />
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Message Input */}
      <div className="p-4 border-t border-gray-200 bg-gray-50">
        <form onSubmit={handleSendMessage} className="flex items-end space-x-2">
          {/* File Upload Button */}
          <button
            type="button"
            onClick={() => setShowFileUpload(!showFileUpload)}
            className="p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-200 rounded-lg transition-colors"
          >
            <FiPaperclip className="w-5 h-5" />
          </button>

          {/* Message Input */}
          <div className="flex-1 relative">
            <textarea
              ref={inputRef}
              value={message}
              onChange={handleTyping}
              onKeyPress={handleKeyPress}
              placeholder="Type your message..."
              className="w-full px-4 py-2 border border-gray-300 rounded-lg resize-none focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
              rows={1}
              style={{ minHeight: '40px', maxHeight: '120px' }}
            />
            
            {/* Emoji Button */}
            <button
              type="button"
              className="absolute right-2 top-1/2 transform -translate-y-1/2 p-1 text-gray-500 hover:text-gray-700 transition-colors"
            >
              <FiSmile className="w-4 h-4" />
            </button>
          </div>

          {/* Send Button */}
          <button
            type="submit"
            disabled={!message.trim() || isSendingMessage}
            className="p-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            <FiSend className="w-5 h-5" />
          </button>
        </form>

        {/* File Upload Modal */}
        {showFileUpload && (
          <FileUpload
            onFileUpload={handleFileUpload}
            onClose={() => setShowFileUpload(false)}
          />
        )}
      </div>
    </div>
  );
};

export default ChatWindow;
